import React from 'react';

function GameBoard({ gameState, playerId, onMove, isMyTurn }) {
  if (!gameState) return <div>Loading...</div>;

  const { board } = gameState;
  const currentPlayer = gameState.players[playerId];

  // Create board layout - 5x5 grid with rooms and hallways
  const boardLayout = [
    ['study', 'study-hall', 'hall', 'hall-lounge', 'lounge'],
    ['study-library', null, 'hall-billiard', null, 'lounge-dining'],
    ['library', 'library-billiard', 'billiard', 'billiard-dining', 'dining'],
    [
      'library-conservatory',
      null,
      'billiard-ballroom',
      null,
      'dining-ballroom',
    ],
    [
      'conservatory',
      'conservatory-ballroom',
      'ballroom',
      'ballroom-kitchen',
      'kitchen',
    ],
  ];

  const getCharacterColor = (character) => {
    const colorMap = {
      'Prof. Plum': '#9b59b6',
      'Mrs. Peacock': '#3498db',
      'Mr. Green': '#27ae60',
      'Miss Scarlet': '#e74c3c',
      'Col. Mustard': '#f1c40f',
      'Mrs. White': '#ecf0f1',
    };
    return colorMap[character] || '#95a5a6';
  };

  const getValidMoves = () => {
    if (!currentPlayer || !isMyTurn) return [];

    const location = currentPlayer.location;
    const validMoves = [];

    if (location.includes('-')) {
      // In hallway - can move to connected rooms
      const hallway = board.hallways[location];
      if (hallway) {
        validMoves.push(...hallway.connects);
      }
    } else {
      // In room - can move to connected hallways or secret passages
      const room = board.rooms[location];
      if (room) {
        // Add connected hallways that are not occupied
        room.doors.forEach((hallwayId) => {
          const hallway = board.hallways[hallwayId];
          if (hallway && !hallway.player) {
            validMoves.push(hallwayId);
          }
        });

        // Add secret passages
        if (board.secretPassages[location]) {
          validMoves.push(board.secretPassages[location]);
        }

        // If player was moved here by another player, they can stay
        if (currentPlayer.lastMovedByPlayer) {
          validMoves.push(location); // Stay in current room
        }
      }
    }

    return validMoves;
  };

  const validMoves = getValidMoves();

  const handleLocationClick = (locationId) => {
    if (isMyTurn && validMoves.includes(locationId)) {
      onMove(locationId);
    }
  };

  const renderLocation = (locationId, row, col) => {
    if (!locationId) {
      return <div key={`${row}-${col}`} className="empty-space"></div>;
    }

    const isRoom = !locationId.includes('-');
    const location = isRoom
      ? board.rooms[locationId]
      : board.hallways[locationId];

    if (!location)
      return <div key={`${row}-${col}`} className="empty-space"></div>;

    const playersInLocation = isRoom
      ? location.players
      : location.player
      ? [location.player]
      : [];
    const isCurrentPlayerLocation =
      currentPlayer && currentPlayer.location === locationId;
    const isValidMove = validMoves.includes(locationId);

    const className = `
      ${isRoom ? 'room' : 'hallway'} 
      ${isCurrentPlayerLocation ? 'current-player' : ''}
      ${location.player && !isRoom ? 'occupied' : ''}
      ${isValidMove ? 'valid-move' : ''}
    `.trim();

    return (
      <div
        key={`${row}-${col}`}
        className={className}
        onClick={() => handleLocationClick(locationId)}
        style={{ cursor: isValidMove ? 'pointer' : 'default' }}
      >
        <div className="location-name">{isRoom ? location.name : ''}</div>

        <div className="players-in-location">
          {playersInLocation.map((character, index) => (
            <div
              key={index}
              className={`character-token character-${character.replace(
                /[.\s]/g,
                '-'
              )}`}
              style={{ backgroundColor: getCharacterColor(character) }}
              title={character}
            >
              {character.charAt(0)}
            </div>
          ))}
        </div>
      </div>
    );
  };

  return (
    <div className="board-container">
      <h3>Game Board</h3>
      <div className="board-grid">
        {boardLayout.map((row, rowIndex) =>
          row.map((locationId, colIndex) =>
            renderLocation(locationId, rowIndex, colIndex)
          )
        )}
      </div>

      {isMyTurn && validMoves.length > 0 && (
        <div className="moves-info">
          <p>
            <strong>Your turn!</strong> Click on a highlighted location to move.
          </p>
          <p>Valid moves: {validMoves.length}</p>
        </div>
      )}

      {isMyTurn && validMoves.length === 0 && (
        <div className="moves-info">
          <p>
            <strong>Your turn!</strong> No moves available - you can only make
            an accusation.
          </p>
        </div>
      )}
    </div>
  );
}

export default GameBoard;
